(function(){
class TurnBook{constructor(el,opts={}){this.el=el;this.opts=opts;this.handlers={};this.current=1;this.setup();}
setup(){this.pages=[...this.el.children];this.total=this.pages.length;this.el.style.perspective='1800px';this.el.style.transformStyle='preserve-3d';this.el.style.position=this.el.style.position||'relative';this.pages.forEach((p,i)=>{p.style.position='absolute';p.style.inset='0';p.style.transformOrigin=(i%2===0)?'left center':'right center';p.style.backfaceVisibility='hidden';p.style.transformStyle='preserve-3d';p.style.transition='transform 420ms ease, z-index 0ms';});this.layout();window.addEventListener('resize',()=>this.layout());}
on(name,fn){(this.handlers[name]||(this.handlers[name]=[])).push(fn)}
emit(name,...args){(this.handlers[name]||[]).forEach(fn=>fn.call(this.el,{type:name},...args));if(this.opts.when&&typeof this.opts.when[name]==='function')this.opts.when[name].call(this.el,{type:name},...args)}
layout(){const w=this.el.clientWidth;const single=this.current===1||this.current===this.total;this.el.style.marginLeft=(this.opts.autoCenter && !single)?'0px':'0px';this.pages.forEach((p,i)=>{const n=i+1;p.style.display='block';p.classList.toggle('left',n%2===0);p.classList.toggle('right',n%2===1);if(n<this.current){p.style.transform='rotateY(-180deg)';p.style.zIndex=1;}else{p.style.transform='rotateY(0deg)';p.style.zIndex=this.total-n+2;}if(n===1||n===this.total){p.style.width='50%';p.style[n===1?'left':'right']='0';}else{p.style.width='50%';p.style[(n%2===0)?'left':'right']='0';}});}
turn(dir){if(dir==='next'&&this.current<this.total){this.emit('turning',this.current+1,[]);this.current++;this.layout();}
if(dir==='previous'&&this.current>1){this.emit('turning',this.current-1,[]);this.current--;this.layout();}}
}
window.TurnBook=TurnBook;
})();
